<script setup lang="ts">
import {ref,onMounted} from 'vue';const rows=ref<any[]>([]),error=ref('');onMounted(async()=>{try{const r=await fetch('/pms/api/invitations/sent',{headers:{Accept:'application/json'}});const d=await r.json();if(!r.ok)throw Error(d.message);rows.value=d.data;}catch(e){error.value=(e as Error).message;}});
</script><template><h3>Previous PMS invitations</h3><p v-if="error" class="notice admin-error">{{error}}</p><div class="admin-list"><p v-if="!rows.length">No previous PMS invitations.</p><article v-for="row in rows" :key="row.id||row.token"><div><strong>{{row.recipient||row.recipient_email}}</strong><p class="muted">{{row.invitable_type}} ? {{row.invitable_name}} ? {{row.project_name}} ? {{row.status}} ? {{row.delivery_status}}</p><input v-if="row.invitation_url" :value="row.invitation_url" readonly aria-label="Previous PMS invitation link"></div></article></div></template>
